from datetime import datetime, timedelta

now = datetime(2026, 11, 23, 10, 0)
edr = [{"serial": "SN-A1", "last": now - timedelta(minutes=23)},
       {"serial": "SN-B2", "last": now - timedelta(days=3)}]
mdm = [{"serial": "SN-A1", "last": now - timedelta(days=232)},
       {"serial": "SN-B2", "last": now - timedelta(hours=1)},
       {"serial": "SN-C3", "last": now - timedelta(minutes=5)}]
dlp = [{"serial": "SN-A1", "last": now - timedelta(minutes=5)},
       {"serial": "SN-C3", "last": now - timedelta(minutes=9)}]
sources = {"EDR": edr, "MDM": mdm, "DLP": dlp}

devices = {}
for name, rows in sources.items():
    for r in rows:
        devices.setdefault(r["serial"], {})[name] = r["last"]

for serial, seen in sorted(devices.items()):
    bad = []
    for name in sources:
        if name not in seen:
            bad.append(f"{name}:미설치")
        elif now - seen[name] > timedelta(days=1):
            bad.append(f"{name}:미통신 {(now - seen[name]).days}일")
    print(serial, "정상" if not bad else ", ".join(bad))

baseline = {"detection_threshold": 30, "suspicious_file_scan": True}
current = {"detection_threshold": 30, "suspicious_file_scan": False}
for k, v in baseline.items():
    if current.get(k) != v:
        print("차이:", k, "기준", v, "지금", current.get(k))

# SN-A1 MDM:미통신 232일
# SN-B2 EDR:미통신 3일, DLP:미설치
# SN-C3 EDR:미설치
# 차이: suspicious_file_scan 기준 True 지금 False
